// Main JavaScript for tools directory functionality

// Configuration
const TOOLS_PER_PAGE = 15;
const MAX_VISIBLE_PAGES = 5;
let allTools = [];
let filteredTools = [];
let currentPage = 1;
let currentFilters = {
    search: '',
    category: '',
    pricing: ['free', 'paid', 'freemium']
};

// DOM Elements
let searchInput, categoryFilter, pricingChecks, toolsGrid, pagination;
let resultsCount, pageInfo, loadingIndicator, activeFiltersContainer;

// Initialize when DOM is loaded
document.addEventListener('DOMContentLoaded', function() {
    initializeElements();
    loadTools();
    setupEventListeners();
});

function initializeElements() {
    searchInput = document.getElementById('searchInput');
    categoryFilter = document.getElementById('categoryFilter');
    pricingChecks = document.querySelectorAll('.pricing-check');
    toolsGrid = document.getElementById('toolsGrid');
    pagination = document.getElementById('pagination');
    resultsCount = document.getElementById('resultsCount');
    pageInfo = document.getElementById('pageInfo');
    loadingIndicator = document.getElementById('loadingIndicator');
    activeFiltersContainer = document.getElementById('activeFilters');
}

// Load tools from JSON file
// Load tools from JSON file
// last update autoselect category
async function loadTools() {
    try {
        allTools = await generateSampleTools(5000);

        updateStats();
        populateCategories();

        autoSelectCategory();   // <-- IMPORTANT: yahin add karna hai

        applyFilters();

        loadingIndicator.style.display = 'none';

        loadCategoriesPreview();

    } catch (error) {
        console.error('Error loading tools:', error);
        loadingIndicator.innerHTML = '<p class="text-danger">Error loading tools. Please refresh the page.</p>';
    }
}
function autoSelectCategory() {
    const urlParams = new URLSearchParams(window.location.search);
    const selectedCategory = urlParams.get("category");

    if (selectedCategory) {
        const categoryFilter = document.getElementById("categoryFilter");

        // Check if the category exists in dropdown
        const exists = [...categoryFilter.options].some(
            opt => opt.value === selectedCategory
        );

        if (exists) {
            categoryFilter.value = selectedCategory;

            if (typeof currentFilters !== "undefined") {
                currentFilters.category = selectedCategory;
            }
        }

        if (typeof applyFilters === "function") {
            applyFilters();
        }

        const section = document.getElementById("tools-section");
        if (section) {
            section.scrollIntoView({
                behavior: "smooth",
                block: "start"
            });
        }
    }
}
